        if (arr[mid] < arr[mid - 1] && arr[mid] < arr[mid + 1]) {
            return arr[mid];
        } else if (arr[mid] < arr[mid - 1]) {
            return findMin(arr, mid + 1, high);
        } else {
            return findMin(arr, low, mid - 1);
        }
    }
}

